reply:
```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:comment "An OWL ontology of educational assessment, modeling assessment kinds, axes of classification (purpose, objectivity, referencing, formality, administration source, standardization, stakes, granularity), test items, rubrics, validity, reliability, feedback and related phenomena, as stated in the source corpus. Where the corpus presents conflicting classification claims (e.g. coordinate lists vs. subordinating statements), both axioms are asserted and the tension is documented in rdfs:comment." .

#################################################################
# ROOT
#################################################################

ea:AssessmentEntity a owl:Class .

#################################################################
# CORE CLASSES: Assessment, Test
#################################################################

ea:Assessment a owl:Class ;
  rdfs:subClassOf ea:AssessmentEntity ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Assessment is often used interchangeably with 'test' but is not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "examination", "exam", "evaluation" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification in some topic, administered verbally, on paper, on computer, or practically." .

ea:hasMeasurementTarget a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:MeasurementTarget ;
  rdfs:comment "Relates an assessment to the kind(s) of attribute it documents; the corpus lists knowledge, skill, attitudes, aptitude and beliefs as non-exclusive targets of a single assessment." .

ea:MeasurementTarget a owl:Class ; rdfs:subClassOf ea:AssessmentEntity .
ea:KnowledgeTarget a owl:Class ; rdfs:subClassOf ea:MeasurementTarget .
ea:SkillTarget a owl:Class ; rdfs:subClassOf ea:MeasurementTarget .
ea:AttitudeTarget a owl:Class ; rdfs:subClassOf ea:MeasurementTarget .
ea:AptitudeTarget a owl:Class ; rdfs:subClassOf ea:MeasurementTarget .
ea:BeliefTarget a owl:Class ; rdfs:subClassOf ea:MeasurementTarget .

#################################################################
# AXIS 1: GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity
                         ea:CourseGranularity ea:ProgramGranularity
                         ea:InstitutionGranularity ea:EducationalSystemGranularity ) .
ea:LearnerGranularity a owl:Class .
ea:LearningCommunityGranularity a owl:Class .
ea:CourseGranularity a owl:Class .
ea:ProgramGranularity a owl:Class .
ea:InstitutionGranularity a owl:Class .
ea:EducationalSystemGranularity a owl:Class .

ea:AssessmentCharacteristic a owl:Class ; rdfs:subClassOf ea:AssessmentEntity .

#################################################################
# AXIS 2: PURPOSE / TIMING  (worked example axis)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .
ea:PlacementPurpose a owl:Class .
ea:FormativePurpose a owl:Class .
ea:SummativePurpose a owl:Class .
ea:DiagnosticPurpose a owl:Class .

ea:PlacementAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  rdfs:comment "Used to place students at the most appropriate point in an instructional sequence; conducted before instruction to establish a baseline; generally not graded." .

ea:FormativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment", "diagnostic testing" ;
  rdfs:comment "Carried out during a course/project to improve learning; not necessarily graded." .

ea:SummativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  skos:altLabel "assessment of learning" ;
  rdfs:comment "Carried out at the end of a course or project; typically graded and used to assign a course grade." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:comment "TENSION: one passage lists 'placement, formative, summative and diagnostic' as four coordinate categories (modeled via the disjoint PurposeCategory partition above), while another passage states 'A common form of formative assessment is diagnostic assessment', subordinating Diagnostic under Formative. Both claims are encoded: DiagnosticPurpose is a disjoint sibling of FormativePurpose in PurposeCategory, AND DiagnosticAssessment is additionally asserted rdfs:subClassOf FormativeAssessment below." .

ea:DiagnosticAssessment rdfs:subClassOf ea:FormativeAssessment .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "A form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# AXIS 3: OBJECTIVITY (applies to Assessment and to TestItem)
#################################################################

ea:ObjectivityCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .
ea:ObjectiveCategory a owl:Class .
ea:SubjectiveCategory a owl:Class .

ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain [ a owl:Class ; owl:unionOf ( ea:Assessment ea:TestItem ) ] ;
  rdfs:range ea:ObjectivityCategory .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning with a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer or way of expressing it." .

ea:ObjectiveQuestion a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveQuestion a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

#################################################################
# AXIS 4: REFERENCING
#################################################################

ea:ReferencingCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:CriterionReferencedCategory ea:NormReferencedCategory ea:IpsativeCategory ) .
ea:CriterionReferencedCategory a owl:Class .
ea:NormReferencedCategory a owl:Class .
ea:IpsativeCategory a owl:Class .

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] ;
  skos:altLabel "standards-based assessment" ;
  rdfs:comment "Candidates are measured against defined, objective criteria regardless of other examinees' scores. It is possible for all test takers to pass or all to fail." .

ea:NormReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] ;
  skos:altLabel "normative assessment", "grading on the curve", "curved grading" ;
  rdfs:comment "Compares a test taker's performance to a reference population (norm group) rather than to fixed criteria." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeCategory ] ) ] ;
  skos:altLabel "forced-choice assessment" ;
  rdfs:comment "Self-comparison, either in the same domain over time or across domains within the same student." .

ea:CriterionReferencedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] ;
  skos:altLabel "CRT" .

ea:NormReferencedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] ;
  skos:altLabel "NRT" .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedTest ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The score an examinee must exceed to pass a (mastery) criterion-referenced test. Not all criterion-referenced tests have a cut score." .

#################################################################
# AXIS 5: FORMALITY
#################################################################

ea:FormalityCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .
ea:FormalCategory a owl:Class .
ea:InformalCategory a owl:Class .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document and is given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Occurs more casually and does not contribute to a final grade; may include observation, checklists, rubrics, portfolios." .

#################################################################
# AXIS 6: ADMINISTRATION SOURCE
#################################################################

ea:AdministrationSourceCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:InternalSourceCategory ea:ExternalSourceCategory ) .
ea:InternalSourceCategory a owl:Class .
ea:ExternalSourceCategory a owl:Class .

ea:hasAdministrationSource a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AdministrationSourceCategory .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationSource ; owl:someValuesFrom ea:InternalSourceCategory ] ) ] ;
  rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationSource ; owl:someValuesFrom ea:ExternalSourceCategory ] ) ] ;
  rdfs:comment "Set by a governing body and marked by unbiased personnel." .

#################################################################
# AXIS 7: STANDARDIZATION (applies to Test)
#################################################################

ea:StandardizationCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .
ea:StandardizedCategory a owl:Class .
ea:NonStandardizedCategory a owl:Class .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent, standard manner for all test takers. Most standardized tests are summative assessments (also stated as a subclass/overlap claim below)." .

ea:StandardizedTest rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ;
  rdfs:comment "Corpus states 'Most standardized tests are summative assessments' - modeled as a (non-exhaustive, 'most') subClassOf restriction; treated loosely since 'most' is not 'all'." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Either significantly different tests are given to different test takers, or the same test is given/evaluated under significantly different conditions." .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

owl:AllDisjointClasses [
  owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                ea:InternationalComparisonTest ea:PsychologicalTest )
] .

#################################################################
# AXIS 8: STAKES
#################################################################

ea:StakesCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .
ea:HighStakesCategory a owl:Class .
ea:LowStakesCategory a owl:Class .

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:StakesCategory .

ea:HighStakesAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  skos:altLabel "high-stakes test" ;
  rdfs:comment "A test/assessment with a desired reward or important consequence for good/poor performance." .

ea:LowStakesAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] ;
  skos:altLabel "low-stakes test" .

#################################################################
# AXIS 9: TEST MODE (written / oral / practical)
#################################################################

ea:TestModeCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:WrittenModeCategory ea:OralModeCategory ea:PracticalModeCategory ) .
ea:WrittenModeCategory a owl:Class .
ea:OralModeCategory a owl:Class .
ea:PracticalModeCategory a owl:Class .

ea:hasTestMode a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestModeCategory .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasTestMode ; owl:someValuesFrom ea:WrittenModeCategory ] ) ] .

ea:OralTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasTestMode ; owl:someValuesFrom ea:OralModeCategory ] ) ] .

ea:PerformanceTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasTestMode ; owl:someValuesFrom ea:PracticalModeCategory ] ) ] ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it, e.g. a behind-the-wheel driving test." .

#################################################################
# COMPETITIVE EXAMINATION (bridge across two axes)
#################################################################

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ]
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ]
  ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected, e.g. civil-service examinations." .

#################################################################
# OTHER NAMED TEST / ASSESSMENT KINDS
#################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A brief assessment covering a small amount of material, usually formative and low-stakes." .

ea:Midterm a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Given near the middle of an academic term; a type of formative or summative assessment (corpus asserts both possibilities)." .

ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Test ;
  skos:altLabel "final exam", "final" ;
  rdfs:comment "A greater form of a unit test given at the conclusion of a course." .

ea:MultipleChoiceTest a owl:Class ; rdfs:subClassOf ea:Test .

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "performance assessment" ;
  rdfs:comment "Requires students to solve real-world problems or produce something with real-world application; similar to summative assessment in focusing on achievement." .

ea:hasPerformanceOutcome a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceOutcomeCategory .

ea:PerformanceOutcomeCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:ProductOutcome ea:PerformanceEventOutcome ) .
ea:ProductOutcome a owl:Class ; rdfs:comment "E.g. a painting, portfolio, paper, or exhibition." .
ea:PerformanceEventOutcome a owl:Class ; rdfs:comment "E.g. a speech, athletic skill, musical recital, or reading." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:PerformanceBasedAssessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside school; corpus states performance assessments 'may also be called authentic assessments', suggesting near-synonymy, yet gives Authentic Assessment its own distinct definition - noted as a tension." .

ea:PortfolioBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "portfolio assessment" .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "benchmark assessment" ;
  rdfs:comment "Used periodically to determine whether students are on track for summative assessments; corpus notes debate on whether interim assessment is formative or summative." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .
ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. a thesis or funding proposal; ambiguous criteria weighting is a documented difficulty." .

#################################################################
# TEST ITEMS
#################################################################

ea:TestItem a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "A component part of a test (stem + possible answers); the general term preferred over 'question' because not all items are phrased as questions." .

ea:isItemOf a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Test .

ea:hasItem a owl:ObjectProperty ;
  owl:inverseOf ea:isItemOf ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestItem .

ea:AnswerOption a owl:Class ; rdfs:subClassOf ea:AssessmentEntity .

ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption ;
  rdfs:comment "The correct answer option(s) of an item." .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption ;
  rdfs:comment "An incorrect answer option." .

ea:hasStem a owl:DatatypeProperty ; rdfs:domain ea:TestItem ; rdfs:range xsd:string .

ea:MultipleChoiceItem a owl:Class ;
  skos:altLabel "MCQ", "multiple-choice question" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerOption ] ) ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerOption ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with MultipleChoiceItem." .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion ;
  rdfs:comment "TENSION: the corpus describes 'True/False' both as a distinct objective question type and, elsewhere, as a 'family' of multiple-choice item requiring selection of all applicable answers." .

ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestion .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestion ;
  skos:altLabel "free response question", "FRQ", "essay question", "extended-response item" .

ea:MultipleChoiceItem rdfs:subClassOf ea:ObjectiveQuestion .
ea:MultipleResponseItem rdfs:subClassOf ea:ObjectiveQuestion .

owl:AllDisjointClasses [
  owl:members ( ea:MultipleChoiceItem ea:TrueFalseItem ea:MultipleResponseItem
                ea:MatchingItem ea:FillInTheBlankItem ea:ShortAnswerItem ea:EssayItem )
] .

ea:hasItemCount a owl:DatatypeProperty ; rdfs:domain ea:Test ; rdfs:range xsd:integer .

#################################################################
# RUBRIC AND GRADING
#################################################################

ea:Rubric a owl:Class ;
  rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses; contains evaluative criteria, quality definitions, and a scoring strategy." .

ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:RubricType a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) ;
  rdfs:comment "TENSION: corpus states rubrics 'can be classified as holistic, analytic, or developmental' (coordinate, modeled as a disjoint partition), but also states 'Developmental rubrics, a subset of analytical rubrics' (subordinate). Both claims are encoded." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Provides an overall rating for a piece of work considering all aspects." .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Evaluates various dimensions or components separately." .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric .

ea:GradingApproach a owl:Class ; rdfs:subClassOf ea:AssessmentEntity .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Takes multiple factors into account criterion-by-criterion when assigning a grade." .

owl:AllDisjointClasses [ owl:members ( ea:HolisticGrading ea:AnalyticGrading ) ] .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Trains raters to score against a scoring guide with multiple criteria; 'comes close to' analytic scoring yet 'remains holistic at heart' - the corpus itself hedges between the two coordinate grading approaches." .

#################################################################
# FEEDBACK
#################################################################

ea:Feedback a owl:Class ; rdfs:subClassOf ea:AssessmentEntity .
ea:hasFeedback a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Feedback .

ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Nonevaluative, supportive, timely, and specific feedback on understanding or performance." .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A subtle correction of a young child's spoken errors by a parent/caregiver." .

#################################################################
# LEARNING OUTCOME
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "A statement about what students should be able to do by the end of a teaching session." .

ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

ea:LearningOutcomeCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:Aim ea:Objective ea:UnintendedLearningOutcome ) .
ea:Aim a owl:Class ; rdfs:comment "Equated with an 'intended' learning outcome." .
ea:Objective a owl:Class ; rdfs:comment "Equated with a 'measured' learning outcome." .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:comment "Beneficial outcomes neither planned nor sought but observed." .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "The degree to which an assessment measures what it is supposed to measure." .

ea:hasValidityEvidence a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .
ea:hasValidityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Validity ; rdfs:range xsd:decimal .

ea:ValidityCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) ;
  rdfs:comment "TENSION: one passage lists content, criterion and construct validity (plus consequential and face validity) as coordinate categories of validity evidence (modeled as a disjoint partition). Another passage states construct validity 'subsumes all other types of validity' and that modern theory treats it as 'the overarching concern ... subsuming all other types of validity evidence such as content validity and criterion validity'. Both claims are encoded: the coordinate partition above, and the subordinating subClassOf axioms below." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "logical validity" ;
  rdfs:comment "Systematic examination of test content to determine whether it covers a representative sample of the behavior domain to be measured." .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "criterion-related validity" ;
  rdfs:comment "Correlation between the test and a criterion variable taken as representative of the construct." .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "Extent to which operationalizations of a construct measure the construct as defined by theory; subsumes all other types of validity." .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "Whether a test appears, on its face, to measure what it purports to measure." .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity owl:disjointUnionOf ( ea:ConvergentValidity ea:DiscriminantValidity ) .
ea:ConvergentValidity a owl:Class ; rdfs:comment "Degree to which two measures of theoretically related constructs are in fact related." .
ea:DiscriminantValidity a owl:Class ; rdfs:comment "Tests whether concepts/measurements supposed to be unrelated are, in fact, unrelated." .

ea:CriterionValidity owl:disjointUnionOf ( ea:ConcurrentValidity ea:PredictiveValidity ) .
ea:ConcurrentValidity a owl:Class ; rdfs:comment "Comparison between the measure and an outcome assessed at the same time." .
ea:PredictiveValidity a owl:Class ; rdfs:comment "Comparison between the measure and an outcome assessed at a later time." .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "The consistency of an assessment; Rx = Vt / Vx, ranging from 0 (unreliable) to 1 (reliable)." .

ea:hasReliabilityEvidence a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .
ea:hasReliabilityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .

ea:ReliabilityEstimateCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) ;
  rdfs:comment "'Several general classes of reliability estimates', modeled as a disjoint partition under Reliability." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree of agreement between two or more raters." .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Degree to which test scores are consistent from one administration to the next; includes intra-rater reliability." .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "parallel-forms reliability", "form equivalence" ;
  rdfs:comment "Degree to which test scores are consistent when methods/instruments vary." .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Consistency of results across items within a test, e.g. measured by Cronbach's alpha." .

ea:ReliabilitySourceCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:StudentRelatedReliability ea:RaterRelatedReliability
                         ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) ;
  rdfs:comment "TENSION: the corpus offers a second, orthogonal four-way taxonomy of 'types of reliability' based on error source (student-, rater-, administration-, and test-related), distinct from the 'general classes of reliability estimates' above; both are modeled as separate disjoint partitions of Reliability." .

ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .

ea:ReliabilityEstimationMethod a owl:Class ;
  rdfs:subClassOf ea:AssessmentEntity ;
  owl:disjointUnionOf ( ea:TestRetestMethod ea:ParallelFormsMethod ea:SplitHalfMethod ea:InternalConsistencyMethod ) ;
  rdfs:comment "Four practical strategies for estimating test reliability." .

ea:TestRetestMethod a owl:Class .
ea:ParallelFormsMethod a owl:Class ; skos:altLabel "equivalent forms method" .
ea:SplitHalfMethod a owl:Class .
ea:InternalConsistencyMethod a owl:Class .

ea:hasEstimationMethod a owl:ObjectProperty ; rdfs:domain ea:Reliability ; rdfs:range ea:ReliabilityEstimationMethod .

#################################################################
# SCORE / TRUE SCORE THEORY
#################################################################

ea:Score a owl:Class ; rdfs:subClassOf ea:AssessmentEntity .
ea:hasScore a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Score .

ea:hasObservedScoreValue a owl:DatatypeProperty ; rdfs:domain ea:Score ; rdfs:range xsd:decimal .
ea:hasTrueScoreValue a owl:DatatypeProperty ; rdfs:domain ea:Score ; rdfs:range xsd:decimal ;
  rdfs:comment "The replicable feature of the concept being measured; X = T + E." .
ea:hasErrorValue a owl:DatatypeProperty ; rdfs:domain ea:Score ; rdfs:range xsd:decimal .
ea:hasPercentileRank a owl:DatatypeProperty ; rdfs:domain ea:Score ; rdfs:range xsd:decimal .

#################################################################
# AUXILIARY PHENOMENA (lightly axiomatized, scoped by corpus)
#################################################################

ea:Proficiency a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "Levels, scales, or cut-off scores on standardized tests and other assessments used to determine whether students meet learning standards." .

ea:CompetencyBasedLearning a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "performance-based learning", "standards-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learned knowledge/skills." .

ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Statistical estimate of a teacher's effect on student learning, derived from standardized-test results." .

ea:ScoreInflation a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "Increase in scores that does not reflect genuine learning improvement." .

ea:MeasurementError a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge/ability, or errors introduced in data collection and reporting." .

ea:TestAnxiety a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "Anxiety experienced when a person believes they are being judged and unlikely to receive a favorable evaluation; more common for high-stakes tests." .

ea:TeachingToTheTest a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "Deliberately narrowing instruction to focus only on material that will be measured on the test." .

ea:Cheating a owl:Class ; rdfs:subClassOf ea:AssessmentEntity ;
  rdfs:comment "Using unauthorized means or methods to obtain a desired test score or grade." .

#################################################################
# LEARNING TYPES (formal/non-formal/informal; tangential but stated)
#################################################################

ea:Learning a owl:Class ; rdfs:subClassOf ea:AssessmentEntity .

ea:LearningFormalityCategory a owl:Class ;
  rdfs:subClassOf ea:AssessmentCharacteristic ;
  owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system, e.g. clubs and workshops." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience and typically does not lead to accreditation." .
