```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
  a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" ;
  rdfs:comment "Models classification claims about educational assessment, testing, reliability, validity, rubrics and related concepts, as stated in the source corpus, including contradictory classification schemes which are retained and flagged." .

#################################################################
#  CORE CLASSES
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "examination", "exam" ;
  rdfs:comment "Assessment is often used interchangeably with test, but assessment is not limited to tests; Test is modeled as a narrower kind of Assessment." .

ea:Examination owl:equivalentClass ea:Test ;
  rdfs:label "examination" ;
  rdfs:comment "An examination (exam) is a test; an educational assessment intended to measure knowledge, skill, aptitude, physical fitness or classification." .

ea:Candidate a owl:Class ;
  rdfs:comment "A student who takes an examination is a candidate." .

ea:Examiner a owl:Class ;
  rdfs:comment "The person who decides how well the candidate has performed." .

ea:ExpertExaminer rdfs:subClassOf ea:Examiner ;
  rdfs:comment "A subject-matter expert examiner, required for complex assessments." .

ea:hasCandidate a owl:ObjectProperty ; rdfs:domain ea:Examination ; rdfs:range ea:Candidate .
ea:hasExaminer   a owl:ObjectProperty ; rdfs:domain ea:Assessment  ; rdfs:range ea:Examiner .
ea:isExaminerOf  a owl:ObjectProperty ; owl:inverseOf ea:hasExaminer .

#################################################################
#  GRANULARITY AXIS
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityCategory .

ea:GranularityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity
                         ea:CourseGranularity ea:ProgramGranularity
                         ea:InstitutionGranularity ea:EducationalSystemGranularity ) ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole (granularity)." .

#################################################################
#  PURPOSE / TIMING AXIS  (placement, formative, summative, diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) ;
  rdfs:comment "Assessment is often divided into placement, formative, summative and diagnostic categories to address different objectives of assessment practice." .

ea:PlacementAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
    )
  ] ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  rdfs:comment "Used to place students according to prior achievement or level of knowledge before instruction; generally not graded." .

ea:FormativeAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ]
    )
  ] ;
  skos:altLabel "educative assessment", "assessment for learning", "formative evaluation",
                "formative feedback", "classroom assessment" ;
  rdfs:comment "Carried out throughout a course to help learning; not necessarily graded; aims to determine whether students understand instruction before a summative assessment." .

ea:SummativeAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ]
    )
  ] ;
  skos:altLabel "assessment of learning", "summative evaluation" ;
  rdfs:comment "Carried out at the end of a course or project; typically graded and used to assign a course grade." .

ea:DiagnosticAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ]
    )
  ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a coordinate category alongside placement, formative and summative assessment (modeled here via the hasPurpose value-partition, which forces pairwise disjointness with FormativeAssessment's purpose value). Another passage states 'A common form of formative assessment is diagnostic assessment' and a further passage calls formative assessment 'a range of ... procedures ... including diagnostic testing', i.e. diagnostic assessment is subordinate to formative assessment. Both claims are encoded (equivalentClass bridge + rdfs:subClassOf), which is logically in tension by design, reflecting the corpus disagreement." .

ea:SelfAssessment rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:TemporalOrientationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:BackwardLookingOrientation ea:ForwardLookingOrientation ) .

ea:hasTemporalOrientation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:TemporalOrientationCategory .

ea:ForwardLookingAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ]
    )
  ] ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
#  OUTCOME FORMAT AXIS (performance-based assessment)
#################################################################

ea:PerformanceOutcomeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ProductOutcome ea:PerformanceOutcome ) ;
  rdfs:comment "Performance formats are further classified into products and performances." .

ea:hasOutcomeFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PerformanceOutcomeCategory .

ea:RealisticPracticalContext a owl:Class ;
  rdfs:comment "A realistic, practical context relevant outside of the school setting." .

ea:hasContext a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:RealisticPracticalContext .

ea:PracticalModeCategory a owl:Class .

ea:hasAdministrationMode a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:AdministrationModeCategory .

ea:PerformanceBasedAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:PracticalModeCategory ]
    )
  ] ;
  skos:altLabel "performance assessment", "performance test", "work sample" ;
  rdfs:comment "Requires an examinee to actually perform a task or activity, often of real-world application; similar to summative assessment in focusing on achievement." .

ea:AuthenticAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasContext ; owl:someValuesFrom ea:RealisticPracticalContext ]
    )
  ] ;
  rdfs:subClassOf ea:PerformanceBasedAssessment ;
  rdfs:comment "TENSION: one passage ('Assessment types include ...') lists AuthenticAssessment and PerformanceBasedAssessment as separate coordinate entries in a flat list, implying siblinghood; another passage states 'Performance assessments may also be called authentic assessments', implying near-equivalence/subordination. Both the sibling listing and the subClassOf relation are retained." .

ea:SimulationAssessment rdfs:subClassOf ea:PerformanceBasedAssessment ;
  rdfs:comment "Some performance tests are simulations, e.g. computerized skill simulations." .

#################################################################
#  OBJECTIVE / SUBJECTIVE AXIS
#################################################################

ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain [ a owl:Class ; owl:unionOf ( ea:Assessment ea:TestItem ) ] ;
  rdfs:range ea:ObjectivityCategory .

ea:ObjectivityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) ;
  rdfs:comment "Assessment is often categorized as either objective or subjective. Some argue this distinction is neither useful nor accurate, since all assessments carry inherent biases." .

ea:ObjectiveAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ]
    )
  ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ]
    )
  ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

ea:ObjectiveQuestionItem owl:equivalentClass [
    owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ]
    )
  ] .

ea:SubjectiveQuestionItem owl:equivalentClass [
    owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ]
    )
  ] .

#################################################################
#  TEST ITEMS
#################################################################

ea:TestItem a owl:Class ;
  rdfs:comment "Consists of a stem (problem/question/incomplete statement) and options; items are stored in an item bank." .

ea:hasItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasItem .

ea:AnswerOption a owl:Class .
ea:Key        rdfs:subClassOf ea:AnswerOption .
ea:Distractor rdfs:subClassOf ea:AnswerOption .
ea:Key owl:disjointWith ea:Distractor .

ea:hasAnswerOption a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption .
ea:isAnswerOptionOf a owl:ObjectProperty ; owl:inverseOf ea:hasAnswerOption .

ea:MultipleChoiceItem owl:equivalentClass [
    owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerOption ; owl:onClass ea:Key ;
        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ]
    )
  ] ;
  rdfs:subClassOf ea:ObjectiveQuestionItem ;
  skos:altLabel "MCQ", "multiple choice question", "objective response" ;
  rdfs:comment "Only one answer may be keyed as correct. Note: the corpus also describes a confusing 'True/False family' of multiple-choice items that allows selecting all correct answers; this family overlaps terminologically with the standalone TrueFalseItem type." .

ea:MultipleResponseItem owl:equivalentClass [
    owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerOption ; owl:onClass ea:Key ;
        owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ]
    )
  ] ;
  rdfs:subClassOf ea:ObjectiveQuestionItem ;
  rdfs:comment "More than one answer may be keyed as correct, contrasted with multiple-choice items." .

ea:OneBestAnswerItem rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Requires the test taker to answer only one from a list of answers." .

ea:TrueFalseItem   rdfs:subClassOf ea:ObjectiveQuestionItem .
ea:MatchingItem    rdfs:subClassOf ea:ObjectiveQuestionItem .
ea:ExtendedResponseItem rdfs:subClassOf ea:SubjectiveQuestionItem .
ea:EssayItem rdfs:subClassOf ea:SubjectiveQuestionItem ;
  skos:altLabel "free response question", "FRQ", "essay question" .
ea:ShortAnswerItem rdfs:subClassOf ea:SubjectiveQuestionItem .

ea:FillInTheBlankItem rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Provides identifying characteristics and requires recall of the correct term." .
ea:WordBankFillInTheBlankItem rdfs:subClassOf ea:FillInTheBlankItem .
ea:OpenRecallFillInTheBlankItem rdfs:subClassOf ea:FillInTheBlankItem .
ea:WordBankFillInTheBlankItem owl:disjointWith ea:OpenRecallFillInTheBlankItem .

ea:MathematicalProblemItem rdfs:subClassOf ea:TestItem ;
  rdfs:comment "States a mathematical problem requiring a freehand response; marks given more for steps than final answer." .

ea:MultipleChoiceTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasItem ; owl:someValuesFrom ea:MultipleChoiceItem ]
    )
  ] .

#################################################################
#  REFERENCING AXIS (criterion / norm / ipsative)
#################################################################

ea:hasReferencing a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory ;
  rdfs:comment "Not declared functional: a test score 'may be interpreted with regard to a norm or criterion, or occasionally both', and the same test paper can be graded by more than one referencing method." .

ea:ReferencingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) ;
  rdfs:comment "Test results can be compared against an established criterion, against the performance of other students (norm), or against previous performance (ipsative)." .

ea:CriterionReferencedAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ]
    )
  ] ;
  skos:altLabel "CRT", "criterion-referenced test", "standards-based assessment" ;
  rdfs:comment "Candidates measured against defined, objective criteria, e.g. the driving test." .

ea:StandardsBasedAssessment owl:equivalentClass ea:CriterionReferencedAssessment .

ea:NormReferencedAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
    )
  ] ;
  skos:altLabel "NRT", "norm-referenced test", "normative assessment", "grading on a curve" ;
  rdfs:comment "Compares test takers to a predefined population sample (the norm/norming group); e.g. IQ tests." .

ea:IpsativeAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ]
    )
  ] ;
  rdfs:comment "Self-comparison either over time in the same domain, or across domains within the same individual." .

ea:NormGroup a owl:Class ;
  skos:altLabel "norming group" ;
  rdfs:comment "The comparison group used to derive norm-referenced scores." .

ea:hasNormGroup a owl:ObjectProperty ; rdfs:domain ea:NormReferencedAssessment ; rdfs:range ea:NormGroup .

ea:hasCutScore a owl:DatatypeProperty ; rdfs:domain ea:CriterionReferencedAssessment ; rdfs:range xsd:decimal .

ea:MasteryTest owl:equivalentClass [
    owl:intersectionOf ( ea:CriterionReferencedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ]
    )
  ] ;
  rdfs:comment "A criterion-referenced test with a cutscore where the examinee passes if the score exceeds it." .

ea:ScoreInterpretation a owl:Class ;
  owl:disjointUnionOf ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) ;
  rdfs:comment "There are two types of test score interpretations." .

ea:hasScoreInterpretation a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:ScoreInterpretation ;
  rdfs:comment "Not functional: either system can be used, and both can apply to the same test." .

#################################################################
#  FORMALITY AXIS
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) ;
  rdfs:comment "Assessment can be either formal or informal." .

ea:FormalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ]
    )
  ] ;
  rdfs:comment "Usually implies a written document; given a numerical score or grade." .

ea:InformalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ]
    )
  ] ;
  rdfs:comment "Occurs more casually; does not contribute to a student's final grade." .

#################################################################
#  ADMINISTRATION LOCUS AXIS (internal / external)
#################################################################

ea:hasAdministeringLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AdministrationLocusCategory .

ea:AdministrationLocusCategory a owl:Class ;
  owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministeringLocus ; owl:someValuesFrom ea:InternalLocus ]
    )
  ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministeringLocus ; owl:someValuesFrom ea:ExternalLocus ]
    )
  ] ;
  rdfs:comment "Set by a governing body and marked by unbiased personnel." .

#################################################################
#  STANDARDIZATION AXIS
#################################################################

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) ;
  rdfs:comment "The opposite of standardized testing is non-standardized testing." .

ea:StandardizedTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ]
    )
  ] ;
  rdfs:comment "Administered and scored in a consistent, standard manner for all test takers." .

ea:NonStandardizedTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ]
    )
  ] ;
  rdfs:comment "Flexible in scope and format, variable in difficulty." .

ea:AchievementTest owl:equivalentClass [
    owl:intersectionOf ( ea:StandardizedTest
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:BackwardLookingOrientation ]
    )
  ] ;
  rdfs:comment "Backward-looking: measures knowledge/skills already learned." .

ea:AptitudeTest owl:equivalentClass [
    owl:intersectionOf ( ea:StandardizedTest
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ]
    )
  ] ;
  rdfs:comment "Forward-looking: attempts to predict future ability to succeed." .

ea:CollegeAdmissionsTest    rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "E.g. PISA, PIRLS, TIMSS." .
ea:PsychologicalTest rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Measures cognitive abilities and mental, emotional, developmental and social characteristics, e.g. the MMPI, IQ tests." .

#################################################################
#  ADMINISTRATION MODE AXIS
#################################################################

ea:AdministrationModeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:VerbalModeCategory ea:WrittenModeCategory ea:OnScreenModeCategory ea:PracticalModeCategory ) ;
  rdfs:comment "A test may be administered verbally, on paper, on a computer, or in a predetermined area requiring demonstration of skills." .

ea:VerbalTest rdfs:subClassOf ea:Test .

ea:WrittenTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:WrittenModeCategory ]
    )
  ] ;
  rdfs:comment "TENSION: defined in one passage as 'administered on paper or on a computer (as an eExam)', which overlaps with OnScreenTest, while another passage lists written test, on-screen test, and practical test as three coordinate (and by the disjoint-union pattern here, mutually exclusive) alternatives." .

ea:OnScreenTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:OnScreenModeCategory ]
    )
  ] ;
  skos:altLabel "computer-based test" .

ea:PracticalTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:PracticalModeCategory ]
    )
  ] .

#################################################################
#  STAKES AXIS
#################################################################

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ]
    )
  ] ;
  rdfs:comment "A test with a desired reward for good performance, or used to make important decisions about students, educators, schools or districts. High-stakes is a function of use, not form." .

ea:LowStakesTest owl:equivalentClass [
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ]
    )
  ] .

ea:CompetitiveExamination rdfs:subClassOf ea:Test, ea:NormReferencedAssessment, ea:HighStakesTest ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

#################################################################
#  OTHER ASSESSMENT TYPES (flat 'assessment types include' list; NOT asserted disjoint,
#  since the corpus explicitly states 'Most tests can be classified on multiple categories'
#  and 'A single test can have multiple qualities')
#################################################################

ea:ContinuousAssessment rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment." .

ea:Portfolio a owl:Class ;
  skos:altLabel "student portfolio", "e-portfolio", "digital portfolio" ;
  rdfs:comment "A compilation of academic work and other evidence assembled to evaluate learning progress." .

ea:hasPortfolio a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Portfolio .
ea:isPortfolioOf a owl:ObjectProperty ; owl:inverseOf ea:hasPortfolio .

ea:PortfolioBasedAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPortfolio ; owl:someValuesFrom ea:Portfolio ]
    )
  ] .

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .
ea:isRubricOf a owl:ObjectProperty ; owl:inverseOf ea:hasRubric .

ea:ComplexAssessment owl:equivalentClass [
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
      [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ]
    )
  ] ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. thesis or funding-proposal assessment." .

#################################################################
#  RUBRIC CLASSIFICATION
#################################################################

ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .

ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: one passage lists holistic, analytic and developmental rubrics as three coordinate classifications (modeled via owl:disjointUnionOf, forcing DevelopmentalRubric disjoint from AnalyticRubric), while the same passage also calls developmental rubrics 'a subset of analytical rubrics' (modeled via rdfs:subClassOf). Both axioms are retained, intentionally producing a logical tension." .

#################################################################
#  GRADING APPROACHES
#################################################################

ea:GradingApproach a owl:Class ;
  owl:disjointUnionOf ( ea:HolisticGrading ea:AnalyticGrading ) ;
  rdfs:comment "Holistic grading contrasts with analytic grading." .

ea:HolisticGrading skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, judged as a whole rather than by separate criteria." .

ea:AnalyticGrading rdfs:comment "Takes more factors into account, scoring criterion by criterion." .

ea:TraitInformedScoring rdfs:subClassOf ea:AnalyticGrading ;
  rdfs:comment "Trains raters to score against a rubric with several criteria; remains holistic at heart by asking raters to consider all traits before a single final score." .

#################################################################
#  VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:ContentValidity rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity rdfs:subClassOf ea:Validity .
ea:FaceValidity rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity rdfs:comment "TENSION: one passage enumerates content, criterion, construct, consequential and face validity as coordinate categories of evidence (modeled above as pairwise disjoint via owl:AllDisjointClasses). Other passages state that construct validity 'subsumes all other types of validity' and that 'modern validity theory defines construct validity as the overarching concern of validity research, subsuming all other types of validity evidence such as content validity and criterion validity' (modeled above as rdfs:subClassOf ea:ConstructValidity for ContentValidity, CriterionValidity and FaceValidity). Both the disjointness and the subsumption are encoded, which is intentionally contradictory." .

ea:CriterionValidity owl:disjointUnionOf ( ea:ConcurrentValidity ea:PredictiveValidity ) ;
  rdfs:comment "Criterion validity is often divided into concurrent and predictive validity based on the timing of measurement." .

ea:ConstructValidity owl:disjointUnionOf ( ea:ConvergentValidity ea:DiscriminantValidity )
  ; rdfs:comment "NOTE: this second disjointUnionOf statement adds Convergent/Discriminant validity as the 'two subtypes of validity that make up construct validity'; OWL allows multiple disjointUnionOf statements, understood as further exhaustive partitions of the class." .

#################################################################
#  RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:ReliabilityEstimate a owl:Class ;
  rdfs:subClassOf ea:Reliability ;
  owl:disjointUnionOf ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) ;
  rdfs:comment "There are several general classes of reliability estimates." .

ea:TestRetestReliability skos:altLabel "repeatability", "temporal stability" ;
  rdfs:comment "Assesses the degree to which test scores are consistent from one administration to the next." .

ea:InterMethodReliability skos:altLabel "parallel-forms reliability", "form equivalence", "alternate-forms reliability" ;
  rdfs:comment "Assesses the degree to which test scores are consistent when there is variation in methods/instruments used." .

ea:InternalConsistencyReliability rdfs:comment "Assesses the consistency of results across items within a test." .

ea:SplitHalfReliability rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms, stepped up via the Spearman-Brown formula." .

ea:ReliabilitySource a owl:Class ;
  rdfs:subClassOf ea:Reliability ;
  owl:disjointUnionOf ( ea:StudentRelatedReliability ea:RaterRelatedReliability
                         ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) ;
  rdfs:comment "There are four types of reliability by source of error: student-related, rater-related, test administration-related, and test-related." .

ea:Score a owl:Class .
ea:TrueScore    rdfs:subClassOf ea:Score .
ea:ObservedScore rdfs:subClassOf ea:Score .
ea:ErrorScore   rdfs:subClassOf ea:Score ;
  rdfs:comment "X = T + E: the observed score equals the true score plus measurement error." .

ea:hasObservedScoreValue a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain ea:Score ; rdfs:range xsd:decimal .
ea:hasTrueScoreValue     a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain ea:Score ; rdfs:range xsd:decimal .
ea:hasErrorValue         a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain ea:Score ; rdfs:range xsd:decimal .

ea:hasReliabilityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:decimal ;
  rdfs:comment "Ranges from 0.00 (much error) to 1.00 (no error)." .

ea:hasItemCount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:integer .

#################################################################
#  LEARNING OUTCOMES / CONSTRUCTIVE ALIGNMENT
#################################################################

ea:LearningOutcome a owl:Class ;
  owl:disjointUnionOf ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) ;
  rdfs:comment "Aims equate to intended learning outcomes, objectives to measured learning outcomes, and a third category is the unintended learning outcome." .

ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .
ea:isLearningOutcomeOf a owl:ObjectProperty ; owl:inverseOf ea:hasLearningOutcome .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "A principle for devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
#  FEEDBACK
#################################################################

ea:Feedback a owl:Class .
ea:CorrectiveFeedback rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Formal or informal feedback on understanding or performance; to be effective it must be nonevaluative, supportive, timely and specific." .

ea:hasFeedback a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Feedback .
ea:isFeedbackOf a owl:ObjectProperty ; owl:inverseOf ea:hasFeedback .

#################################################################
#  MEASUREMENT PHENOMENA
#################################################################

ea:MeasurementError a owl:Class ;
  rdfs:comment "The difference between what a test score indicates and a student's actual knowledge/abilities, or errors introduced in data collection/reporting." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Student scores increase without genuine improvement in learning." .

ea:TestAnxiety a owl:Class ;
  rdfs:comment "Anxiety occurring when a person believes they are being judged and unlikely to receive a favorable evaluation." .

ea:TeachingToTheTest a owl:Class ;
  rdfs:comment "Deliberately narrowing instruction to focus only on material that will be measured on the test." .

ea:Cheating a owl:Class ;
  rdfs:comment "Using unauthorized means or methods to obtain a desired test score or grade." .

ea:ValueAddedMeasure a owl:Class ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Statistical estimate of a teacher's effect on student learning, used in teacher evaluation." .

#################################################################
#  LEARNING CATEGORIES (non-formal / informal learning, mentioned alongside formal/informal assessment)
#################################################################

ea:Learning a owl:Class .
ea:NonFormalLearning rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience; typically does not lead to accreditation." .
ea:NonFormalLearning owl:disjointWith ea:InformalLearning .
